export const capabilityPaths=[
 {id:'robotics',title:'Make a robot move with purpose',tag:'ROBOTICS & CONTROL',symbol:'↗',question:'Where is the tool, where should it go, and how can we tell?',now:'Coordinates, signed numbers, angles, ratios, and functions turn a position into something you can calculate.',bridge:'Vectors and trigonometry describe directions. Linear algebra describes transformations. Calculus and differential equations describe motion and feedback.',later:'Kinematics, sensing, estimation, controls, and verification connect a mathematical model to hardware that behaves reliably.',example:'A tool moves 3 cm east and 4 cm north. Its displacement has length 5 cm, but its path length was 7 cm. Those are different questions. Naming the quantity correctly comes before choosing the formula.',stage:'geometry',lab:'vector',source:{title:'NASA: the Cupola and its robotics workstation',url:'https://www.nasa.gov/international-space-station/cupola/'},prompt:'Draw a coordinate system. Explain the difference between where the robot ends and how far it travelled.'},
 {id:'orbits',title:'Understand how a spacecraft travels',tag:'FLIGHT & ORBITAL MOTION',symbol:'◌',question:'What path follows from position, velocity, and the forces acting?',now:'Fractions, exponents, rearranging equations, geometry, and units prepare you to use a model without losing its meaning.',bridge:'Trigonometry, vectors, calculus, and differential equations describe changing positions and velocities. Numerical methods approximate solutions when a tidy formula is unavailable.',later:'Orbital mechanics, flight dynamics, navigation, and mission analysis combine physics, computation, observations, and uncertainty.',example:'At a constant speed of 2 m/s for 6 s, a teaching model predicts 12 m of travel. If the speed changes, that simple multiplication needs a new justification. Calculus eventually gives you a language for accumulating changing rates.',stage:'algebra',lab:'orbit',source:{title:'NASA: orbital mechanics',url:'https://science.nasa.gov/learn/basics-of-space-flight/chapter3-1/'},prompt:'Explain when distance = speed × time is valid. Give a case where one constant speed cannot describe the whole motion.'},
 {id:'power',title:'Keep a spacecraft operating',tag:'POWER & ENERGY',symbol:'ϟ',question:'Can the system meet its needs throughout the mission?',now:'Arithmetic, percentages, ratios, time conversions, and reading a graph let you make and check an energy budget.',bridge:'Functions describe changing demand. Calculus accumulates energy use. Circuit theory and thermodynamics connect the budget to a physical system.',later:'Power systems, thermal control, reliability, and operations make tradeoffs among available energy, mass, environment, and mission requirements.',example:'A hypothetical 40 W load running for 3 h uses 120 Wh. A 200 Wh usable supply leaves 80 Wh in this simple model. A real design must address changing loads, conversion losses, temperature, ageing, and reserves.',stage:'arithmetic',lab:'power',source:{title:'EIA: measuring electricity',url:'https://www.eia.gov/energyexplained/electricity/measuring-electricity.php'},prompt:'Distinguish watts from watt-hours in one sentence, then check the units in your calculation.'},
 {id:'structures',title:'Build things that keep their shape',tag:'STRUCTURES & MATERIALS',symbol:'△',question:'How does a structure respond to loads, and what evidence supports its use?',now:'Geometry, scale, powers, equations, and clear diagrams help you distinguish length, area, volume, and physical quantities.',bridge:'Statics, mechanics of materials, calculus, linear algebra, and numerical methods allow more detailed models of stress, strain, deformation, and vibration.',later:'Structural analysis, materials selection, manufacturing, testing, and inspection must agree. A beautiful simulation cannot compensate for an incorrect load or boundary condition.',example:'If every length of a similar solid doubles, its area becomes four times as large and its volume eight times as large. This does not mean a hollow spacecraft structure has eight times the mass: wall thickness and its design can change.',stage:'geometry',lab:'scale',source:{title:'OpenStax: volume and surface area',url:'https://openstax.org/books/prealgebra-2e/pages/9-6-solve-geometry-applications-volume-and-surface-area'},prompt:'Write the scale factors for length, area, and volume when k = 3. State which physical properties geometry alone cannot determine.'},
 {id:'habitats',title:'Make living in space more workable',tag:'HABITATS & HUMAN SYSTEMS',symbol:'⌂',question:'What must a habitat provide, and how do its systems interact?',now:'Rates, proportions, inventory arithmetic, unit conversions, graphs, and inequalities let you describe supply, consumption, and limits.',bridge:'Chemistry, thermodynamics, fluid mechanics, controls, and systems engineering extend simple balances into interacting physical processes.',later:'Life-support engineering, human factors, maintenance, logistics, and operations combine technical performance with the needs of people using the system.',example:'A teaching inventory begins at 60 units. If 8 units are added and 11 used, 57 remain. The operation is simple; engineering asks whether every relevant flow is included, measured correctly, and available at the right time.',stage:'prealgebra',lab:'line',source:{title:'NASA: environmental control and life support systems',url:'https://www.nasa.gov/reference/environmental-control-and-life-support-systems-eclss/'},prompt:'Draw an inventory box with arrows in and out. Name three assumptions you would need before trusting its forecast.'},
 {id:'aerodynamics',title:'Understand how flight is possible',tag:'AERODYNAMICS & FLUIDS',symbol:'≈',question:'How do motion, pressure, geometry, and the environment interact?',now:'Ratios, functions, graphs, scientific notation, and units prepare you to compare quantities and notice trends.',bridge:'Mechanics, calculus, differential equations, dimensional analysis, and fluid mechanics reveal what simple formulas assume and where they fail.',later:'Aerodynamics, propulsion, computational fluid dynamics, wind-tunnel testing, and flight testing join models to measured behaviour.',example:'In a model where an output is proportional to speed squared, doubling the speed multiplies that output by four if the other inputs remain fixed. The exponent tells you how sensitive the relationship is; the conditions determine whether the model applies.',stage:'algebra2',lab:'line',source:{title:'NASA: the four forces on an airplane',url:'https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/four-forces-on-an-airplane/'},prompt:'Compare doubling an input in y = 3x and y = 3x². Explain why their outputs change by different factors.'}
];

